354.     private void processCancelMessage() {
355.         // From https://www.postgresql.org/docs/current/protocol-flow.html :
356.         // To issue a cancel request, the frontend opens a new connection to the server and sends a CancelRequest message, rather than the StartupMessage message
357.         // that would ordinarily be sent across a new connection. The server will process this request and then close the connection.
358.         // For security reasons, no direct reply is made to the cancel request message.
359.         int pid = getIntUnsafe(recvBufReadPos); // thread id really
360.         recvBufReadPos += Integer.BYTES;
361.         int secret = getIntUnsafe(recvBufReadPos);
362.         recvBufReadPos += Integer.BYTES;
363.         LOG.info().$("cancel request [pid=").$(pid).I$();
364.         try {
365.             registry.cancel(pid, secret);
366.         } catch (CairoException e) { // error message should not be sent to client
367.             LOG.error().$safe(e.getFlyweightMessage()).$();
368.         }
369.     }
