371.     private int processInitMessage() throws PGMessageProcessingException {
372.         int availableToRead = availableToRead();
373.         if (availableToRead < Integer.BYTES) { // size of message
374.             return SocketAuthenticator.NEEDS_READ;
375.         }
376.         int msgLen = getIntUnsafe(recvBufReadPos);
377.         if (msgLen > availableToRead) {
378.             return SocketAuthenticator.NEEDS_READ;
379.         }
380.         // at this point we have a full message available ready to be processed
381.         recvBufReadPos += Integer.BYTES; // first move beyond the msgLen
382.         int protocol = getIntUnsafe(recvBufReadPos);
383.         recvBufReadPos += Integer.BYTES;
384. 
385.         switch (protocol) {
386.             case INIT_STARTUP_MESSAGE:
387.                 processStartupMessage(msgLen);
388.                 break;
389.             case INIT_CANCEL_REQUEST:
390.                 processCancelMessage();
391.                 return SocketAuthenticator.NEEDS_DISCONNECT;
392.             case INIT_SSL_REQUEST:
393.                 compactRecvBuf();
394.                 prepareSslResponse();
395.                 state = State.WRITE_AND_EXPECT_INIT_MESSAGE;
396.                 break;
397.             case INIT_GSS_REQUEST:
398.                 compactRecvBuf();
399.                 prepareGssResponse();
400.                 state = State.WRITE_AND_EXPECT_INIT_MESSAGE;
401.                 break;
402.             default:
403.                 LOG.error().$("unknown init message [protocol=").$(protocol).$(']').$();
404.                 throw PGMessageProcessingException.INSTANCE;
405.         }
406.         return SocketAuthenticator.OK;
407.     }
