409.     private int processPasswordMessage() throws PGMessageProcessingException {
410.         int availableToRead = availableToRead();
411.         if (availableToRead < 1 + Integer.BYTES) { // msgType + msgLen
412.             return SocketAuthenticator.NEEDS_READ;
413.         }
414.         byte msgType = Unsafe.getUnsafe().getByte(recvBufReadPos);
415.         assert msgType == MESSAGE_TYPE_PASSWORD_MESSAGE;
416. 
417.         int msgLen = getIntUnsafe(recvBufReadPos + 1);
418.         long msgLimit = (recvBufReadPos + msgLen + 1); // +1 for the type byte which is not included in msgLen
419.         if (recvBufWritePos < msgLimit) {
420.             return SocketAuthenticator.NEEDS_READ;
421.         }
422. 
423.         // at this point we have a full message available ready to be processed
424.         recvBufReadPos += 1 + Integer.BYTES; // first move beyond the msgType and msgLen
425. 
426.         long hi = PGConnectionContext.getUtf8StrSize(recvBufReadPos, msgLimit, "bad password length", null);
427.         authType = verifyPassword(username, recvBufReadPos, (int) (hi - recvBufReadPos));
428.         if (authType != AUTH_TYPE_NONE) {
429.             recvBufReadPos = msgLimit;
430.             state = State.AUTH_SUCCESS;
431.         } else {
432.             LOG.info().$("bad password for user [user=").$(username).$(']').$();
433.             prepareErrorResponse("invalid username/password");
434.             state = State.WRITE_AND_AUTH_FAILURE;
435.         }
436.         return SocketAuthenticator.OK;
437.     }
