439.     private void processStartupMessage(int msgLen) throws PGMessageProcessingException {
440.         long msgLimit = (recvBufStart + msgLen);
441.         long lo = recvBufReadPos;
442. 
443.         // there is an extra byte at the end, and it has to be 0
444.         while (lo < msgLimit - 1) {
445.             final long nameLo = lo;
446.             final long nameHi = PGConnectionContext.getUtf8StrSize(lo, msgLimit, "malformed property name", null);
447.             final long valueLo = nameHi + 1;
448.             final long valueHi = PGConnectionContext.getUtf8StrSize(valueLo, msgLimit, "malformed property value", null);
449.             lo = valueHi + 1;
450. 
451.             // store user
452.             if (PGKeywords.isUser(nameLo, nameHi - nameLo)) {
453.                 CharacterStoreEntry e = characterStore.newEntry();
454.                 e.put(dus.of(valueLo, valueHi, false));
455.                 this.username = e.toImmutable();
456.             }
457.             boolean parsed = true;
458.             if (PGKeywords.isOptions(nameLo, nameHi - nameLo)) {
459.                 if (PGKeywords.startsWithTimeoutOption(valueLo, valueHi - valueLo)) {
460.                     try {
461.                         dus.of(valueLo + 21, valueHi, false);
462.                         long statementTimeout = Numbers.parseLong(dus);
463.                         optionsListener.setSqlTimeout(statementTimeout);
464.                     } catch (NumericException ex) {
465.                         parsed = false;
466.                     }
467.                 } else {
468.                     parsed = false;
469.                 }
470.             }

