package io.questdb.test.cutlass.pgwire;

import io.questdb.mp.WorkerPool;
import io.questdb.std.Os;
import org.junit.Test;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Properties;

public class ZZZDiagProtocol32Test extends BasePGTest {

    @Test
    public void testProtocol32Negotiation() throws Exception {
        setUp();
        try {
            try (
                    final PGServer server = createPGServer(2);
                    WorkerPool workerPool = server.getWorkerPool()
            ) {
                workerPool.start(LOG);
                for (int i = 0; i < 60000 && !server.isListening(); i++) {
                    Os.sleep(1);
                }
                int port = server.getPort();

                Properties properties = new Properties();
                properties.setProperty("user", "admin");
                properties.setProperty("password", "quest");
                properties.setProperty("sslmode", "disable");
                properties.setProperty("protocolVersion", "3.2");
                final String url = String.format("jdbc:postgresql://127.0.0.1:%d/qdb", port);
                System.out.println("DIAG: connecting with protocolVersion=3.2 ...");
                try (Connection connection = DriverManager.getConnection(url, properties)) {
                    System.out.println("DIAG: CONNECTED with 3.2");
                    try (Statement st = connection.createStatement()) {
                        ResultSet rs = st.executeQuery("select 1 as x");
                        rs.next();
                        System.out.println("DIAG: query result x=" + rs.getInt(1));
                    }
                } catch (Throwable t) {
                    System.out.println("DIAG: 3.2 FAILED: " + t);
                    Throwable c = t.getCause();
                    while (c != null) {
                        System.out.println("DIAG:   caused by: " + c);
                        c = c.getCause();
                    }
                }
            }
        } finally {
            tearDown();
        }
    }
}

