package io.questdb.test.griffin.engine.functions.catalogue;

import io.questdb.test.AbstractCairoTest;
import org.junit.Test;

public class ZZZDiagCurrentCatalogTest extends AbstractCairoTest {

    private void tryQ(String sql) {
        try {
            assertSql("", sql); // will print mismatch but we only care about exceptions
        } catch (Throwable t) {
            System.out.println("DIAGQ [" + sql + "] -> EXCEPTION: " + t.getClass().getSimpleName() + ": " + t.getMessage());
            return;
        }
        System.out.println("DIAGQ [" + sql + "] -> OK (no exception)");
    }

    @Test
    public void testBareKeywords() throws Exception {
        assertMemoryLeak(() -> {
            tryQ("select current_user");
            tryQ("select current_user()");
            tryQ("select current_schema");
            tryQ("select current_schema()");
            tryQ("select current_database");
            tryQ("select current_database()");
            tryQ("select current_catalog");
            tryQ("select current_catalog()");
        });
    }
}

