package io.questdb.test.cutlass.pgwire;

import io.questdb.cutlass.pgwire.IPGWireServer;
import io.questdb.mp.WorkerPool;
import io.questdb.test.tools.TestUtils;
import org.junit.Assert;
import org.junit.Test;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Properties;

public class ZZZVerify77Test extends BasePGTest {

    public ZZZVerify77Test() {
        super(LegacyMode.MODERN);
    }

    @Test
    public void testCurrentCatalogAndProtocol32() throws Exception {
        assertMemoryLeak(() -> {
            try (
                    final IPGWireServer server = createPGServer(2);
                    final WorkerPool workerPool = server.getWorkerPool()
            ) {
                workerPool.start(LOG);

                // 1) protocol 3.2 must connect (NegotiateProtocolVersion path)
                Properties props = new Properties();
                props.setProperty("user", "admin");
                props.setProperty("password", "quest");
                props.setProperty("sslmode", "disable");
                props.setProperty("protocolVersion", "3.2");
                final String url = String.format("jdbc:postgresql://127.0.0.1:%d/qdb", server.getPort());
                try (Connection c = java.sql.DriverManager.getConnection(url, props)) {
                    Assert.assertFalse(c.isClosed());
                    // getCatalog triggers `select current_catalog` on 42.7.7
                    String cat = c.getCatalog();
                    Assert.assertEquals("qdb", cat);
                    try (Statement st = c.createStatement();
                         ResultSet rs = st.executeQuery("select current_catalog")) {
                        Assert.assertTrue(rs.next());
                        Assert.assertEquals("qdb", rs.getString(1));
                    }
                }

                // 2) default protocol connection still works
                try (Connection c = getConnection(server.getPort(), false, true)) {
                    Assert.assertEquals("qdb", c.getCatalog());
                }
            }
        });
    }
}

